// Spring Boot - Add Referrer-Policy via Security Configuration
// SecurityConfig.java

import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.security.config.annotation.web.builders.HttpSecurity;
import org.springframework.security.config.annotation.web.configuration.EnableWebSecurity;
import org.springframework.security.web.SecurityFilterChain;
import org.springframework.security.web.header.writers.ReferrerPolicyHeaderWriter;

@Configuration
@EnableWebSecurity
public class SecurityConfig {

    @Bean
    public SecurityFilterChain securityFilterChain(HttpSecurity http) throws Exception {
        http
            .headers(headers -> headers
                // Recommended: strict-origin-when-cross-origin
                .referrerPolicy(referrer -> referrer
                    .policy(ReferrerPolicyHeaderWriter.ReferrerPolicy.STRICT_ORIGIN_WHEN_CROSS_ORIGIN)
                )

                // Alternative policies:
                // .policy(ReferrerPolicyHeaderWriter.ReferrerPolicy.NO_REFERRER)
                // .policy(ReferrerPolicyHeaderWriter.ReferrerPolicy.SAME_ORIGIN)
                // .policy(ReferrerPolicyHeaderWriter.ReferrerPolicy.ORIGIN)
            )
            .authorizeHttpRequests(auth -> auth
                .anyRequest().permitAll()
            );

        return http.build();
    }
}

// Alternative: Manual Filter approach
import javax.servlet.*;
import javax.servlet.http.HttpServletResponse;
import java.io.IOException;
import org.springframework.stereotype.Component;

@Component
public class SecurityHeadersFilter implements Filter {

    @Override
    public void doFilter(ServletRequest request, ServletResponse response, 
                        FilterChain chain) throws IOException, ServletException {
        HttpServletResponse httpResponse = (HttpServletResponse) response;

        // Set Referrer-Policy header
        httpResponse.setHeader("Referrer-Policy", "strict-origin-when-cross-origin");

        // Other common values:
        // httpResponse.setHeader("Referrer-Policy", "no-referrer");
        // httpResponse.setHeader("Referrer-Policy", "same-origin");
        // httpResponse.setHeader("Referrer-Policy", "origin");

        chain.doFilter(request, response);
    }
}

