// JUnit test to verify Referrer-Policy header
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.test.web.servlet.MockMvc;

import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;

@SpringBootTest
@AutoConfigureMockMvc
public class ReferrerPolicyTest {

    @Autowired
    private MockMvc mockMvc;

    @Test
    public void shouldHaveReferrerPolicyHeader() throws Exception {
        mockMvc.perform(get("/"))
            .andExpect(status().isOk())
            .andExpect(header().exists("Referrer-Policy"))
            .andExpect(header().string("Referrer-Policy", 
                "strict-origin-when-cross-origin"));
    }

    @Test
    public void allEndpointsShouldHaveHeader() throws Exception {
        String[] endpoints = {"/", "/api/data", "/login", "/search"};

        for (String endpoint : endpoints) {
            mockMvc.perform(get(endpoint))
                .andExpect(header().exists("Referrer-Policy"));
        }
    }

    @Test
    public void shouldNotUseUnsafePolicy() throws Exception {
        // Verify not using 'unsafe-url' which leaks full URL always
        String policy = mockMvc.perform(get("/"))
            .andReturn()
            .getResponse()
            .getHeader("Referrer-Policy");

        assertNotNull(policy);
        assertNotEquals("unsafe-url", policy);
    }
}

