// Express.js - Add Referrer-Policy via helmet middleware
const express = require('express');
const helmet = require('helmet');

const app = express();

// Method 1: Use helmet with recommended policy (included by default)
app.use(helmet());
// Default: no-referrer

// Method 2: Customize referrer policy
app.use(
  helmet.referrerPolicy({
    policy: 'strict-origin-when-cross-origin'  // Recommended
    // Other options:
    // policy: 'no-referrer'
    // policy: 'same-origin'
    // policy: 'origin'
    // policy: 'origin-when-cross-origin'
  })
);

// Method 3: Manual middleware (if not using helmet)
app.use((req, res, next) => {
  res.setHeader('Referrer-Policy', 'strict-origin-when-cross-origin');
  next();
});

// Method 4: Multiple policies (fallback support)
app.use((req, res, next) => {
  // Browser uses first supported policy
  res.setHeader(
    'Referrer-Policy', 
    'no-referrer, strict-origin-when-cross-origin'
  );
  next();
});

// Method 5: Different policies for different routes
app.get('/public', (req, res, next) => {
  res.setHeader('Referrer-Policy', 'origin-when-cross-origin');
  next();
});

app.get('/sensitive', (req, res, next) => {
  res.setHeader('Referrer-Policy', 'no-referrer');
  next();
});

app.get('/', (req, res) => {
  res.send('<h1>Protected with Referrer-Policy</h1>');
});

app.listen(3000, () => {
  console.log('Server running with Referrer-Policy protection');
});

