const request = require('supertest');
const { expect } = require('chai');
const app = require('../app');

describe('Referrer-Policy Header Tests', () => {
  it('should have Referrer-Policy header', (done) => {
    request(app)
      .get('/')
      .expect(200)
      .end((err, res) => {
        if (err) return done(err);
        expect(res.headers['referrer-policy']).to.exist;
        done();
      });
  });

  it('should use recommended policy', (done) => {
    request(app)
      .get('/')
      .end((err, res) => {
        if (err) return done(err);

        const policy = res.headers['referrer-policy'];
        const recommendedPolicies = [
          'strict-origin-when-cross-origin',
          'no-referrer',
          'same-origin'
        ];

        expect(recommendedPolicies).to.include(policy);
        done();
      });
  });

  it('should not use unsafe-url policy', (done) => {
    request(app)
      .get('/')
      .end((err, res) => {
        if (err) return done(err);

        const policy = res.headers['referrer-policy'];
        expect(policy).to.not.equal('unsafe-url');

        done();
      });
  });

  it('should protect all routes', (done) => {
    const routes = ['/', '/api/data', '/search'];
    let completed = 0;

    routes.forEach(route => {
      request(app)
        .get(route)
        .end((err, res) => {
          if (!err) {
            expect(res.headers['referrer-policy']).to.exist;
          }
          completed++;
          if (completed === routes.length) done();
        });
    });
  });
});

