using Microsoft.Extensions.DependencyInjection;

var builder = WebApplication.CreateBuilder(args);

builder.Services.AddControllersWithViews();

var app = builder.Build();

// Method 1: Simple middleware
app.Use(async (context, next) =>
{
    // Recommended policy
    context.Response.Headers.Add(
        "Referrer-Policy", 
        "strict-origin-when-cross-origin"
    );

    // Alternative policies:
    // context.Response.Headers.Add("Referrer-Policy", "no-referrer");
    // context.Response.Headers.Add("Referrer-Policy", "same-origin");
    // context.Response.Headers.Add("Referrer-Policy", "origin");

    await next();
});

app.UseRouting();
app.UseAuthorization();

app.MapControllerRoute(
    name: "default",
    pattern: "{controller=Home}/{action=Index}/{id?}");

app.Run();

// Alternative: Reusable middleware class
public class ReferrerPolicyMiddleware
{
    private readonly RequestDelegate _next;
    private readonly string _policy;

    public ReferrerPolicyMiddleware(
        RequestDelegate next, 
        string policy = "strict-origin-when-cross-origin")
    {
        _next = next;
        _policy = policy;
    }

    public async Task InvokeAsync(HttpContext context)
    {
        context.Response.Headers.Add("Referrer-Policy", _policy);
        await _next(context);
    }
}

// Extension method
public static class ReferrerPolicyExtensions
{
    public static IApplicationBuilder UseReferrerPolicy(
        this IApplicationBuilder builder, 
        string policy = "strict-origin-when-cross-origin")
    {
        return builder.UseMiddleware<ReferrerPolicyMiddleware>(policy);
    }
}

