// Selenium test for Referrer-Policy validation
import org.openqa.selenium.WebDriver;
import org.openqa.selenium.chrome.ChromeDriver;
import org.openqa.selenium.chrome.ChromeOptions;
import org.testng.annotations.Test;
import org.testng.Assert;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.net.URI;

public class ReferrerPolicyTest {

    @Test
    public void verifyReferrerPolicyPresent() throws Exception {
        HttpClient client = HttpClient.newHttpClient();
        HttpRequest request = HttpRequest.newBuilder()
            .uri(new URI("https://your-domain.com"))
            .GET()
            .build();

        HttpResponse<String> response = client.send(
            request, 
            HttpResponse.BodyHandlers.ofString()
        );

        var headers = response.headers();
        Assert.assertTrue(
            headers.firstValue("Referrer-Policy").isPresent(),
            "Referrer-Policy header should be present"
        );
    }

    @Test
    public void verifySecureReferrerPolicy() throws Exception {
        HttpClient client = HttpClient.newHttpClient();
        HttpRequest request = HttpRequest.newBuilder()
            .uri(new URI("https://your-domain.com"))
            .GET()
            .build();

        HttpResponse<String> response = client.send(
            request, 
            HttpResponse.BodyHandlers.ofString()
        );

        String policy = response.headers()
            .firstValue("Referrer-Policy")
            .orElse("");

        String[] securePolicies = {
            "strict-origin-when-cross-origin",
            "no-referrer",
            "same-origin",
            "strict-origin",
            "origin"
        };

        boolean isSecure = false;
        for (String securePolicy : securePolicies) {
            if (policy.equals(securePolicy)) {
                isSecure = true;
                break;
            }
        }

        Assert.assertTrue(isSecure, 
            "Referrer-Policy should use secure value, got: " + policy);
    }

    @Test
    public void verifyNotUnsafeUrl() throws Exception {
        HttpClient client = HttpClient.newHttpClient();
        HttpRequest request = HttpRequest.newBuilder()
            .uri(new URI("https://your-domain.com"))
            .GET()
            .build();

        HttpResponse<String> response = client.send(
            request, 
            HttpResponse.BodyHandlers.ofString()
        );

        String policy = response.headers()
            .firstValue("Referrer-Policy")
            .orElse("");

        Assert.assertNotEquals("unsafe-url", policy,
            "Should not use unsafe-url policy");
    }
}
